/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        PanelToGroupBox(scwin.panel_3);
        $c.fil.setObjectValue(ipt_txb_EMP_NM, $c.session.getUserInfo("empNm"));
        scwin.fn_SetCode();
        scwin.dts_CloseProcs.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=PERSONONDUTY_HISTORY_IN";
        scwin.dts_CloseProcs.reset();
        scwin.fn_OneSearch();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31010.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_OneGrid = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_OneGrid')) : $c.util.getComponent('dts_OneGrid');

scwin.dts_DutyStatus = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_DutyStatus')) : $c.util.getComponent('dts_DutyStatus');

scwin.dts_CloseProcs = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_CloseProcs')) : $c.util.getComponent('dts_CloseProcs');

scwin.dts_Grid = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Grid')) : $c.util.getComponent('dts_Grid');

scwin.dts_CodeEmpNo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_CodeEmpNo')) : $c.util.getComponent('dts_CodeEmpNo');

scwin.dts_CodeChrgEmpNo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_CodeChrgEmpNo')) : $c.util.getComponent('dts_CodeChrgEmpNo');

scwin.gLdMktTp = undefined; try { scwin.gLdMktTp = /* sdd-asis-lifecycle:begin gLdMktTp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("market")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31010' }); }

scwin.gDutyID = undefined; try { scwin.gDutyID = /* sdd-asis-lifecycle:begin gDutyID — as-is 원문 본문(전환 이관 · 포팅 적용됨) */js_duty/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31010' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf31010.onpageload' });
    }
};


