*/
scwin.setTime = function () {
    /* sdd-asis-lifecycle:begin fn_setTime — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const vCurDate = $c.date.formatDate("yyyy-mm-dd hh:mm:ss");
    $c.fil.setObjectValue(ipt_txbNow, "현재시각 : " + vCurDate);
    scwin.runClock();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.runClock
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.runClock = function () {
    /* sdd-asis-lifecycle:begin runClock — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    setTimeout(function(){ scwin.setTime() }, 1000);
    /* sdd-asis-lifecycle:end */
};


